select 'f71ad666-fea1-5262-ac96-4a277e410b37', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Una vía por el páramo","text":"El departamento planea pavimentar una vía que cruza un páramo para unir dos municipios. Estas son algunas opiniones:\nTransportador: «Hoy gastamos seis horas en un trayecto de ochenta kilómetros. Con la vía, los productos llegarían frescos y más baratos.»\nBióloga: «El páramo regula el agua que consumen miles de personas. Una vía trae tráfico, basuras y nuevos asentamientos.»\nCampesina de la zona: «Necesitamos sacar la papa y llevar a los niños al colegio, pero también vivimos del agua del páramo.»\nAlcalde: «La obra generará empleo durante la construcción y atraerá turismo.»","svg":null,"table":null}'::jsonb, '¿Qué le preocupa principalmente a la bióloga?', '[{"label":"A","text":"El empleo que se generaría durante la construcción.","is_correct":false,"distractor_type":"Atribuye a la bióloga el argumento del alcalde.","explanation_feedback":"Incorrecta. Ese es el argumento del alcalde."},{"label":"B","text":"La falta de colegios en la zona rural.","is_correct":false,"distractor_type":"Atribuye a la bióloga una parte de lo que dice la campesina.","explanation_feedback":"Incorrecta. Eso lo menciona la campesina."},{"label":"C","text":"El tiempo que tardan los productos en llegar al mercado.","is_correct":false,"distractor_type":"Atribuye a la bióloga la preocupación del transportador.","explanation_feedback":"Incorrecta. Esa es la preocupación del transportador."},{"label":"D","text":"Los efectos de la vía sobre el páramo y el agua que este regula.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Ella destaca que el páramo regula el agua y que la vía traería tráfico, basuras y asentamientos."}]'::jsonb, null, 0.9, -1.2, 0.25, 50, 'original_generated'
from public.evidences e where e.code = 'SC.E4.1'
on conflict (id) do nothing;
