select '3e4f2d19-d836-5a2f-9e85-16585525d39b', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Una encuesta en el colegio","text":"Para un artículo del periódico escolar, un estudiante preguntó a 20 compañeros de su curso si estaban de acuerdo con eliminar el uniforme. Dieciséis dijeron que sí. El titular del artículo fue: «Los jóvenes colombianos rechazan el uniforme escolar».","svg":null,"table":null}'::jsonb, '¿Cuál es el principal problema del titular?', '[{"label":"A","text":"Ningún estudiante debería opinar sobre el uniforme.","is_correct":false,"distractor_type":"Descalifica a los participantes.","explanation_feedback":"Incorrecta. Los estudiantes sí pueden opinar; el problema es generalizar."},{"label":"B","text":"Dieciséis de veinte es una minoría.","is_correct":false,"distractor_type":"Lee mal la proporción.","explanation_feedback":"Incorrecta. Dieciséis de veinte es el 80 %, una mayoría en ese grupo."},{"label":"C","text":"Generaliza a todos los jóvenes del país una opinión de solo 20 estudiantes de un curso.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Una muestra de 20 compañeros de un curso no representa a todos los jóvenes colombianos."},{"label":"D","text":"Usa porcentajes cuando debía usar números.","is_correct":false,"distractor_type":"Se fija en la forma y no en la generalización.","explanation_feedback":"Incorrecta. El problema no es el formato de los datos sino el alcance de la conclusión."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
from public.evidences e where e.code = 'SC.E3.2'
on conflict (id) do nothing;
