select 'b1697b45-af54-58eb-acf4-163cf5afd66c', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Una encuesta en el colegio","text":"Para un artículo del periódico escolar, un estudiante preguntó a 20 compañeros de su curso si estaban de acuerdo con eliminar el uniforme. Dieciséis dijeron que sí. El titular del artículo fue: «Los jóvenes colombianos rechazan el uniforme escolar».","svg":null,"table":null}'::jsonb, '¿Qué conclusión sí podría sostenerse con esos datos?', '[{"label":"A","text":"Los profesores también quieren eliminar el uniforme.","is_correct":false,"distractor_type":"Atribuye opiniones a quienes no respondieron.","explanation_feedback":"Incorrecta. No se preguntó a los profesores."},{"label":"B","text":"La mayoría de los estudiantes del colegio rechaza el uniforme.","is_correct":false,"distractor_type":"Generaliza al colegio sin datos de otros cursos.","explanation_feedback":"Incorrecta. Solo se preguntó en un curso."},{"label":"C","text":"El Ministerio de Educación debe eliminar el uniforme.","is_correct":false,"distractor_type":"Salta de una opinión a una decisión nacional.","explanation_feedback":"Incorrecta. Veinte respuestas no sustentan una política nacional."},{"label":"D","text":"La mayoría de los encuestados de ese curso está de acuerdo con eliminar el uniforme.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La conclusión se limita al grupo que realmente respondió."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E3.2'
on conflict (id) do nothing;
