select '59253be3-ba3b-5e07-8bcf-044eb859a06b', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Carta de un artesano (recreación)","text":"«Bogotá, 1850. Señor Presidente: los artesanos de esta ciudad vemos con angustia cómo llegan cada mes barcos con zapatos, telas y muebles fabricados en Inglaterra, que se venden más baratos que los nuestros porque casi no pagan impuestos al entrar. Pedimos que se aumenten los aranceles a esas mercancías para que nuestros talleres no se cierren y nuestras familias no pasen hambre.»\n(Texto creado con fines educativos a partir de las discusiones de la época.)","svg":null,"table":null}'::jsonb, '¿En qué debate económico de mediados del siglo XIX se ubica esta carta?', '[{"label":"A","text":"Entre el uso del petróleo y el del carbón.","is_correct":false,"distractor_type":"Ubica la carta en otra época y tema.","explanation_feedback":"Incorrecta. La carta habla de manufacturas importadas."},{"label":"B","text":"Entre la monarquía y la república.","is_correct":false,"distractor_type":"Ubica la carta en un debate político anterior.","explanation_feedback":"Incorrecta. La carta trata de impuestos a importaciones, no de la forma de gobierno."},{"label":"C","text":"Entre la reforma agraria y la industrialización del siglo XX.","is_correct":false,"distractor_type":"Ubica la carta en otro siglo.","explanation_feedback":"Incorrecta. La carta es de 1850 y trata de aranceles."},{"label":"D","text":"Entre el libre comercio y la protección de la producción nacional.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El artesano pide subir los aranceles a productos importados para proteger su trabajo frente al libre comercio."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E3.1'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'e0030a4e-90e6-51db-b083-935a9bd616a5', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Carta de un artesano (recreación)","text":"«Bogotá, 1850. Señor Presidente: los artesanos de esta ciudad vemos con angustia cómo llegan cada mes barcos con zapatos, telas y muebles fabricados en Inglaterra, que se venden más baratos que los nuestros porque casi no pagan impuestos al entrar. Pedimos que se aumenten los aranceles a esas mercancías para que nuestros talleres no se cierren y nuestras familias no pasen hambre.»\n(Texto creado con fines educativos a partir de las discusiones de la época.)","svg":null,"table":null}'::jsonb, '¿Qué grupo de la época probablemente estaría en desacuerdo con la petición del artesano?', '[{"label":"A","text":"Los comerciantes que importaban y vendían productos ingleses.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Subir los aranceles encarecería sus mercancías y reduciría sus ventas."},{"label":"B","text":"Las familias de los artesanos de Bogotá.","is_correct":false,"distractor_type":"Ignora que la carta defiende a esas familias.","explanation_feedback":"Incorrecta. La carta habla en nombre de esas familias."},{"label":"C","text":"Los dueños de talleres de zapatos en Bogotá.","is_correct":false,"distractor_type":"Ignora que son parte del grupo que firma.","explanation_feedback":"Incorrecta. Ellos se beneficiarían de la medida."},{"label":"D","text":"Los artesanos de otras ciudades del país.","is_correct":false,"distractor_type":"Supone que otros artesanos tendrían intereses opuestos.","explanation_feedback":"Incorrecta. Otros artesanos probablemente compartirían la petición."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E4.1'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '601c1838-5a64-5fee-a912-860439b32802', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Carta de un artesano (recreación)","text":"«Bogotá, 1850. Señor Presidente: los artesanos de esta ciudad vemos con angustia cómo llegan cada mes barcos con zapatos, telas y muebles fabricados en Inglaterra, que se venden más baratos que los nuestros porque casi no pagan impuestos al entrar. Pedimos que se aumenten los aranceles a esas mercancías para que nuestros talleres no se cierren y nuestras familias no pasen hambre.»\n(Texto creado con fines educativos a partir de las discusiones de la época.)","svg":null,"table":null}'::jsonb, 'Un estudiante quiere usar esta carta para afirmar que todos los colombianos de 1850 querían aranceles altos. ¿Por qué no es suficiente?', '[{"label":"A","text":"Porque en 1850 no existían impuestos a las importaciones.","is_correct":false,"distractor_type":"Contradice la fuente.","explanation_feedback":"Incorrecta. La carta menciona impuestos a las importaciones."},{"label":"B","text":"Porque la carta fue escrita en Inglaterra.","is_correct":false,"distractor_type":"Lee mal la fuente.","explanation_feedback":"Incorrecta. La carta fue escrita en Bogotá."},{"label":"C","text":"Porque la carta expresa los intereses de un grupo concreto, no de toda la población.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Una fuente muestra la posición de quien la escribe; para generalizar se necesitarían otras fuentes."},{"label":"D","text":"Porque las cartas nunca sirven como fuentes históricas.","is_correct":false,"distractor_type":"Descalifica todo un tipo de fuente.","explanation_feedback":"Incorrecta. Las cartas sí son fuentes, pero tienen alcances limitados."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E3.2'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '6a39abfb-5a12-5d20-9127-24c0befa02f2', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Opiniones en una red social","text":"Comentario 1: «Los jóvenes de hoy no quieren trabajar; solo piensan en el celular.»\nComentario 2: «Según el DANE, en el último año aumentó el número de jóvenes que ni estudian ni trabajan; habría que analizar por qué.»\nComentario 3: «Los del campo no saben de tecnología, por eso no vale la pena llevarles internet.»\n(Comentarios inventados con fines educativos.)","svg":null,"table":null}'::jsonb, '¿Qué tienen en común los comentarios 1 y 3?', '[{"label":"A","text":"Ambos citan estadísticas oficiales.","is_correct":false,"distractor_type":"Confunde los comentarios con el 2.","explanation_feedback":"Incorrecta. El que cita una fuente es el comentario 2."},{"label":"B","text":"Ambos hablan de la misma región del país.","is_correct":false,"distractor_type":"Inventa un rasgo común.","explanation_feedback":"Incorrecta. Ninguno menciona una región específica."},{"label":"C","text":"Atribuyen una característica negativa a todo un grupo sin pruebas.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Ambos generalizan sobre «los jóvenes» y «los del campo», es decir, expresan prejuicios."},{"label":"D","text":"Ambos proponen analizar las causas de un problema.","is_correct":false,"distractor_type":"Atribuye la actitud del comentario 2.","explanation_feedback":"Incorrecta. Es el comentario 2 el que propone analizar causas."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E3.3'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '8668832e-cded-5909-8717-513b6cac22ca', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Opiniones en una red social","text":"Comentario 1: «Los jóvenes de hoy no quieren trabajar; solo piensan en el celular.»\nComentario 2: «Según el DANE, en el último año aumentó el número de jóvenes que ni estudian ni trabajan; habría que analizar por qué.»\nComentario 3: «Los del campo no saben de tecnología, por eso no vale la pena llevarles internet.»\n(Comentarios inventados con fines educativos.)","svg":null,"table":null}'::jsonb, '¿Qué intención se puede reconocer en el comentario 3?', '[{"label":"A","text":"Proponer clases de tecnología en las zonas rurales.","is_correct":false,"distractor_type":"Inventa una propuesta.","explanation_feedback":"Incorrecta. El comentario no propone formación; descarta invertir."},{"label":"B","text":"Justificar que no se invierta en internet para el campo con base en un prejuicio.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Usa un prejuicio sobre los campesinos para concluir que no vale la pena llevarles internet."},{"label":"C","text":"Defender el derecho de los campesinos a la tecnología.","is_correct":false,"distractor_type":"Invierte la intención.","explanation_feedback":"Incorrecta. El comentario concluye lo contrario."},{"label":"D","text":"Mostrar datos sobre el acceso a internet en el campo.","is_correct":false,"distractor_type":"Supone que presenta información.","explanation_feedback":"Incorrecta. El comentario no da datos; afirma una generalización."}]'::jsonb, null, 1.3, 1.3, 0.25, 60, 'original_generated'
from public.evidences e where e.code = 'SC.E3.3'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'c5f1ea79-1520-5fc5-99c1-4b40bf5fc01a', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Opiniones en una red social","text":"Comentario 1: «Los jóvenes de hoy no quieren trabajar; solo piensan en el celular.»\nComentario 2: «Según el DANE, en el último año aumentó el número de jóvenes que ni estudian ni trabajan; habría que analizar por qué.»\nComentario 3: «Los del campo no saben de tecnología, por eso no vale la pena llevarles internet.»\n(Comentarios inventados con fines educativos.)","svg":null,"table":null}'::jsonb, '¿Por qué el comentario 2 es más útil para un debate que el comentario 1?', '[{"label":"A","text":"Porque es más corto y fácil de leer.","is_correct":false,"distractor_type":"Se fija en la forma.","explanation_feedback":"Incorrecta. La extensión no hace más útil un argumento."},{"label":"B","text":"Porque se apoya en una fuente y plantea buscar causas, en lugar de culpar a un grupo.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Cita un dato verificable y propone análisis, mientras que el 1 solo generaliza."},{"label":"C","text":"Porque usa palabras más emocionales.","is_correct":false,"distractor_type":"Confunde emoción con solidez.","explanation_feedback":"Incorrecta. Las palabras emocionales no hacen más útil un argumento."},{"label":"D","text":"Porque dice que los jóvenes no quieren trabajar.","is_correct":false,"distractor_type":"Atribuye al 2 la idea del 1.","explanation_feedback":"Incorrecta. Eso lo dice el comentario 1."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E3.2'
