insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'e14c031f-1a1f-58dd-a5e4-67f2fcf5c7b4', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"El agua de La Guajira","text":"En una zona de La Guajira con sequías frecuentes, distintos actores discuten cómo garantizar el agua:\nAutoridad wayuu: «El agua es sagrada y nuestros pozos tradicionales deben ser respetados. Cualquier proyecto debe consultarse con nuestras comunidades.»\nEmpresa minera: «Nuestra operación genera regalías y empleos. Usamos agua bajo los permisos que nos dio el Estado.»\nFuncionario del Gobierno: «Instalaremos plantas desalinizadoras y carrotanques mientras construimos un acueducto regional.»\nMédica de un puesto de salud: «Los niños llegan con diarrea y desnutrición; el agua que consumen muchas veces no es potable.»","svg":null,"table":null}'::jsonb, '¿Qué influye principalmente en la posición de la autoridad wayuu?', '[{"label":"A","text":"Su cosmovisión, en la que el agua tiene un valor sagrado y colectivo.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Su argumento parte de que el agua es sagrada y de su derecho a ser consultados."},{"label":"B","text":"El interés de recibir regalías mineras.","is_correct":false,"distractor_type":"Le atribuye el argumento de la empresa.","explanation_feedback":"Incorrecta. Las regalías las menciona la empresa."},{"label":"C","text":"La necesidad de cumplir un plan de gobierno.","is_correct":false,"distractor_type":"Le atribuye el rol del funcionario.","explanation_feedback":"Incorrecta. Ese es el enfoque del funcionario."},{"label":"D","text":"Su formación médica sobre enfermedades.","is_correct":false,"distractor_type":"Le atribuye el rol de la médica.","explanation_feedback":"Incorrecta. Ese enfoque es el de la médica."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E4.2'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '66e397ac-32b9-58fc-b620-6ff7543047e7', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"El agua de La Guajira","text":"En una zona de La Guajira con sequías frecuentes, distintos actores discuten cómo garantizar el agua:\nAutoridad wayuu: «El agua es sagrada y nuestros pozos tradicionales deben ser respetados. Cualquier proyecto debe consultarse con nuestras comunidades.»\nEmpresa minera: «Nuestra operación genera regalías y empleos. Usamos agua bajo los permisos que nos dio el Estado.»\nFuncionario del Gobierno: «Instalaremos plantas desalinizadoras y carrotanques mientras construimos un acueducto regional.»\nMédica de un puesto de salud: «Los niños llegan con diarrea y desnutrición; el agua que consumen muchas veces no es potable.»","svg":null,"table":null}'::jsonb, '¿Qué solución responde a la exigencia de la autoridad wayuu?', '[{"label":"A","text":"Construir el acueducto sin informar a las comunidades para ahorrar tiempo.","is_correct":false,"distractor_type":"Contradice la exigencia.","explanation_feedback":"Incorrecta. Ignorar a las comunidades va contra lo que pide la autoridad wayuu."},{"label":"B","text":"Aumentar las regalías que paga la empresa al municipio.","is_correct":false,"distractor_type":"Responde al interés de la empresa o del Estado.","explanation_feedback":"Incorrecta. Más regalías no garantizan la consulta que pide la autoridad wayuu."},{"label":"C","text":"Diseñar los proyectos de agua mediante consulta previa con las comunidades.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La autoridad wayuu exige que cualquier proyecto se consulte con sus comunidades."},{"label":"D","text":"Cerrar los pozos tradicionales y reemplazarlos por carrotanques.","is_correct":false,"distractor_type":"Contradice la exigencia.","explanation_feedback":"Incorrecta. La autoridad wayuu pide respetar los pozos."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E4.3'
on conflict (id) do nothing;
