select '1e3714d8-4805-5c9b-82e5-dadccef572bf', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"El agua de La Guajira","text":"En una zona de La Guajira con sequías frecuentes, distintos actores discuten cómo garantizar el agua:\nAutoridad wayuu: «El agua es sagrada y nuestros pozos tradicionales deben ser respetados. Cualquier proyecto debe consultarse con nuestras comunidades.»\nEmpresa minera: «Nuestra operación genera regalías y empleos. Usamos agua bajo los permisos que nos dio el Estado.»\nFuncionario del Gobierno: «Instalaremos plantas desalinizadoras y carrotanques mientras construimos un acueducto regional.»\nMédica de un puesto de salud: «Los niños llegan con diarrea y desnutrición; el agua que consumen muchas veces no es potable.»","svg":null,"table":null}'::jsonb, '¿Qué aporta la médica a la discusión que no aportan los demás?', '[{"label":"A","text":"Una propuesta para construir un acueducto regional.","is_correct":false,"distractor_type":"Le atribuye la propuesta del funcionario.","explanation_feedback":"Incorrecta. Esa propuesta es del funcionario."},{"label":"B","text":"Evidencia sobre los efectos del agua no potable en la salud de los niños.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Ella describe consecuencias concretas en la salud que observa en su trabajo."},{"label":"C","text":"Una defensa de los permisos de uso de agua de la empresa.","is_correct":false,"distractor_type":"Le atribuye el argumento de la empresa.","explanation_feedback":"Incorrecta. Eso lo dice la empresa."},{"label":"D","text":"Una explicación del valor sagrado del agua.","is_correct":false,"distractor_type":"Le atribuye el argumento wayuu.","explanation_feedback":"Incorrecta. Eso lo dice la autoridad wayuu."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E4.1'
