insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'd51f6fd6-8b4f-5ce8-81a2-fe614f18e8e7', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Dos relatos de una huelga (recreación)","text":"Fuente A, periódico de la época: «Agitadores llevaron a los trabajadores a abandonar sus labores, causando graves pérdidas a la empresa y desorden en la región.»\nFuente B, testimonio de un trabajador recogido años después: «Trabajábamos doce horas, nos pagaban con vales que solo servían en las tiendas de la compañía y no teníamos hospital. Paramos porque nadie nos escuchaba.»\n(Fuentes recreadas con fines educativos.)","svg":null,"table":null}'::jsonb, '¿Qué intención se puede reconocer en el uso de la palabra «agitadores» en la fuente A?', '[{"label":"A","text":"Presentar la huelga como obra de unos pocos y quitarle legitimidad a los reclamos.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Llamar «agitadores» a los organizadores sugiere que la huelga no respondía a problemas reales."},{"label":"B","text":"Describir con exactitud las condiciones laborales.","is_correct":false,"distractor_type":"Supone neutralidad en la fuente.","explanation_feedback":"Incorrecta. La fuente A no menciona las condiciones de trabajo."},{"label":"C","text":"Explicar por qué los trabajadores pararon.","is_correct":false,"distractor_type":"Atribuye a la fuente A el contenido de la B.","explanation_feedback":"Incorrecta. Las razones del paro las da la fuente B."},{"label":"D","text":"Defender las peticiones de los trabajadores.","is_correct":false,"distractor_type":"Invierte la intención.","explanation_feedback":"Incorrecta. La fuente A culpa a los huelguistas por las pérdidas."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E3.3'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '1852f9c0-c575-5f12-8f6f-83d1a72538fd', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Dos relatos de una huelga (recreación)","text":"Fuente A, periódico de la época: «Agitadores llevaron a los trabajadores a abandonar sus labores, causando graves pérdidas a la empresa y desorden en la región.»\nFuente B, testimonio de un trabajador recogido años después: «Trabajábamos doce horas, nos pagaban con vales que solo servían en las tiendas de la compañía y no teníamos hospital. Paramos porque nadie nos escuchaba.»\n(Fuentes recreadas con fines educativos.)","svg":null,"table":null}'::jsonb, '¿Qué limitación tiene la fuente B para explicar lo ocurrido?', '[{"label":"A","text":"No sirve porque la escribió un trabajador y no un periodista.","is_correct":false,"distractor_type":"Descalifica la fuente por el autor.","explanation_feedback":"Incorrecta. Un testimonio de un trabajador sí es una fuente válida."},{"label":"B","text":"No menciona ninguna condición de trabajo.","is_correct":false,"distractor_type":"Lee mal la fuente.","explanation_feedback":"Incorrecta. La fuente B describe jornadas, pagos y falta de hospital."},{"label":"C","text":"Es un recuerdo personal registrado años después, que puede tener olvidos o una sola mirada.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Los testimonios tardíos son valiosos, pero conviene contrastarlos con otras fuentes."},{"label":"D","text":"Contradice todos los documentos de la época.","is_correct":false,"distractor_type":"Inventa información.","explanation_feedback":"Incorrecta. No se sabe si contradice todos los documentos."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E3.2'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'f251a604-0a61-5125-8f65-74e8ac963c16', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Dos relatos de una huelga (recreación)","text":"Fuente A, periódico de la época: «Agitadores llevaron a los trabajadores a abandonar sus labores, causando graves pérdidas a la empresa y desorden en la región.»\nFuente B, testimonio de un trabajador recogido años después: «Trabajábamos doce horas, nos pagaban con vales que solo servían en las tiendas de la compañía y no teníamos hospital. Paramos porque nadie nos escuchaba.»\n(Fuentes recreadas con fines educativos.)","svg":null,"table":null}'::jsonb, 'Si se comparan las dos fuentes, ¿en qué se diferencian sus perspectivas?', '[{"label":"A","text":"Ambas coinciden en culpar a los trabajadores.","is_correct":false,"distractor_type":"Ignora la fuente B.","explanation_feedback":"Incorrecta. La fuente B justifica el paro."},{"label":"B","text":"Ninguna de las dos fuentes menciona a la empresa.","is_correct":false,"distractor_type":"Lee mal las fuentes.","explanation_feedback":"Incorrecta. Ambas mencionan a la empresa o la compañía."},{"label":"C","text":"La A habla de salarios y la B del desorden en la región.","is_correct":false,"distractor_type":"Invierte el contenido.","explanation_feedback":"Incorrecta. La A habla de desorden y la B de salarios y condiciones."},{"label":"D","text":"La A enfatiza las pérdidas de la empresa y la B las condiciones de los trabajadores.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Cada fuente pone el foco en los intereses del grupo con el que se identifica."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E4.1'
on conflict (id) do nothing;
