select 'd3a7b289-b7d4-55a8-a656-4ae0bf474080', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"El parque del barrio","text":"La junta de acción comunal de un barrio discute qué hacer con un lote vacío:\nDon Hernando, 70 años: «Necesitamos un parque con bancas y sombra para caminar tranquilos.»\nValentina, 16 años: «Lo que falta es una cancha; los jóvenes no tenemos dónde hacer deporte.»\nMarta, madre de dos niños pequeños: «Un parque infantil cerrado, para que los niños jueguen seguros.»\nComerciante: «Mejor un parqueadero; los clientes no tienen dónde dejar el carro.»","svg":null,"table":null}'::jsonb, '¿Qué propone Valentina para el lote?', '[{"label":"A","text":"Un parqueadero para clientes.","is_correct":false,"distractor_type":"Confunde su propuesta con la del comerciante.","explanation_feedback":"Incorrecta. Eso lo propone el comerciante."},{"label":"B","text":"Un parque infantil cerrado.","is_correct":false,"distractor_type":"Confunde su propuesta con la de Marta.","explanation_feedback":"Incorrecta. Eso lo propone Marta."},{"label":"C","text":"Un parque con bancas y sombra.","is_correct":false,"distractor_type":"Confunde su propuesta con la de don Hernando.","explanation_feedback":"Incorrecta. Eso lo propone don Hernando."},{"label":"D","text":"Una cancha para hacer deporte.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Ella dice que los jóvenes no tienen dónde hacer deporte."}]'::jsonb, null, 0.9, -1.2, 0.25, 40, 'original_generated'
from public.evidences e where e.code = 'SC.E4.1'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'b7b98777-d7e9-5de9-915b-b9e52b7a34fe', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"El parque del barrio","text":"La junta de acción comunal de un barrio discute qué hacer con un lote vacío:\nDon Hernando, 70 años: «Necesitamos un parque con bancas y sombra para caminar tranquilos.»\nValentina, 16 años: «Lo que falta es una cancha; los jóvenes no tenemos dónde hacer deporte.»\nMarta, madre de dos niños pequeños: «Un parque infantil cerrado, para que los niños jueguen seguros.»\nComerciante: «Mejor un parqueadero; los clientes no tienen dónde dejar el carro.»","svg":null,"table":null}'::jsonb, '¿Qué explica mejor que cada persona proponga algo distinto?', '[{"label":"A","text":"Todos quieren lo mismo, pero lo dicen distinto.","is_correct":false,"distractor_type":"Ignora que las propuestas son distintas.","explanation_feedback":"Incorrecta. Las propuestas son diferentes: cancha, parque, parqueadero."},{"label":"B","text":"La junta les pidió que no se pusieran de acuerdo.","is_correct":false,"distractor_type":"Inventa un dato.","explanation_feedback":"Incorrecta. El texto no dice eso."},{"label":"C","text":"Sus edades y roles hacen que tengan necesidades diferentes.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Un adulto mayor, una joven, una madre y un comerciante viven el barrio de maneras distintas."},{"label":"D","text":"Ninguno conoce bien el barrio donde vive.","is_correct":false,"distractor_type":"Descalifica a los participantes.","explanation_feedback":"Incorrecta. Todos hablan desde su experiencia en el barrio."}]'::jsonb, null, 0.9, -1.2, 0.25, 45, 'original_generated'
from public.evidences e where e.code = 'SC.E4.2'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '7634c138-fc2b-597d-9235-e92cdbb09f6c', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"El parque del barrio","text":"La junta de acción comunal de un barrio discute qué hacer con un lote vacío:\nDon Hernando, 70 años: «Necesitamos un parque con bancas y sombra para caminar tranquilos.»\nValentina, 16 años: «Lo que falta es una cancha; los jóvenes no tenemos dónde hacer deporte.»\nMarta, madre de dos niños pequeños: «Un parque infantil cerrado, para que los niños jueguen seguros.»\nComerciante: «Mejor un parqueadero; los clientes no tienen dónde dejar el carro.»","svg":null,"table":null}'::jsonb, '¿Qué propuesta tendría en cuenta a la mayoría de las personas que hablaron?', '[{"label":"A","text":"Un espacio con zona infantil, una pequeña cancha y caminos con bancas.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Combina las necesidades de don Hernando, Valentina y Marta."},{"label":"B","text":"Un parqueadero con una banca a la entrada.","is_correct":false,"distractor_type":"Prioriza al comerciante.","explanation_feedback":"Incorrecta. Solo responde a una persona."},{"label":"C","text":"Dejar el lote vacío para evitar discusiones.","is_correct":false,"distractor_type":"Evita el conflicto sin resolverlo.","explanation_feedback":"Incorrecta. No atiende ninguna de las necesidades."},{"label":"D","text":"Una cancha grande que ocupe todo el lote.","is_correct":false,"distractor_type":"Prioriza solo a Valentina.","explanation_feedback":"Incorrecta. Deja por fuera a don Hernando y a Marta."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E4.3'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '88df723c-b1a0-5c28-9ef9-eeed1dbef5a5', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Un informe sobre deforestación","text":"Un informe de una organización ambiental afirma: «La deforestación en la Amazonía colombiana aumentó por la expansión de la ganadería y los cultivos ilícitos.» El informe incluye imágenes satelitales de varios años, pero no explica cómo se calcularon las cifras de hectáreas.","svg":null,"table":null}'::jsonb, '¿Qué haría falta para usar este informe con más confianza en un trabajo de clase?', '[{"label":"A","text":"Copiar la conclusión sin revisar nada, porque viene de expertos.","is_correct":false,"distractor_type":"Acepta la fuente sin evaluarla.","explanation_feedback":"Incorrecta. Incluso las fuentes expertas deben contrastarse."},{"label":"B","text":"Conocer la metodología usada y contrastar las cifras con otras fuentes, como el monitoreo oficial.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Saber cómo se calcularon las cifras y compararlas con otras fuentes da más solidez."},{"label":"C","text":"Descartarlo porque toda organización ambiental exagera.","is_correct":false,"distractor_type":"Descalifica la fuente por quién la produce.","explanation_feedback":"Incorrecta. Una fuente no se descarta por su autor; se evalúa su método."},{"label":"D","text":"Usar solo las imágenes, porque una imagen nunca necesita explicación.","is_correct":false,"distractor_type":"Supone que las imágenes hablan solas.","explanation_feedback":"Incorrecta. Las imágenes también requieren saber cómo se interpretan."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E3.2'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'fc75b8b9-d650-5459-a4ac-995923a104f1', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Un informe sobre deforestación","text":"Un informe de una organización ambiental afirma: «La deforestación en la Amazonía colombiana aumentó por la expansión de la ganadería y los cultivos ilícitos.» El informe incluye imágenes satelitales de varios años, pero no explica cómo se calcularon las cifras de hectáreas.","svg":null,"table":null}'::jsonb, '¿Qué aporta de valor el informe, a pesar de su limitación?', '[{"label":"A","text":"Una explicación detallada de cómo se calcularon las cifras.","is_correct":false,"distractor_type":"Contradice el texto.","explanation_feedback":"Incorrecta. El texto dice que no explica el cálculo."},{"label":"B","text":"Imágenes satelitales que permiten observar cambios en la cobertura de bosque.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Las imágenes de varios años son evidencia útil sobre la pérdida de bosque."},{"label":"C","text":"Entrevistas con todos los ganaderos de la región.","is_correct":false,"distractor_type":"Inventa contenido.","explanation_feedback":"Incorrecta. El informe no menciona entrevistas."},{"label":"D","text":"La opinión del Gobierno sobre la deforestación.","is_correct":false,"distractor_type":"Inventa contenido.","explanation_feedback":"Incorrecta. El informe es de una organización ambiental."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E3.2'
