insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'f461acec-824e-56bf-abe1-fbdd2d5c533c', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Un discurso de campaña (ficticio)","text":"«Nuestra ciudad era tranquila hasta que llegaron los de afuera. Desde entonces hay más robos y menos trabajo. Si votan por mí, haré que esta ciudad vuelva a ser de los nuestros.»","svg":null,"table":null}'::jsonb, '¿Qué prejuicio contiene el discurso?', '[{"label":"A","text":"Supone que los votantes no saben leer.","is_correct":false,"distractor_type":"Inventa un prejuicio.","explanation_feedback":"Incorrecta. El discurso no habla de la educación de los votantes."},{"label":"B","text":"Afirma que la ciudad nunca fue tranquila.","is_correct":false,"distractor_type":"Lee al revés el discurso.","explanation_feedback":"Incorrecta. El discurso dice que antes era tranquila."},{"label":"C","text":"Defiende los derechos de las personas migrantes.","is_correct":false,"distractor_type":"Invierte el sentido.","explanation_feedback":"Incorrecta. El discurso rechaza a «los de afuera»."},{"label":"D","text":"Culpa a las personas que llegaron de otros lugares de los robos y del desempleo.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Asocia sin pruebas a los migrantes con el delito y la falta de trabajo."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E3.3'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '833cea87-9eee-5789-a219-efa6b35e3c3f', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Un discurso de campaña (ficticio)","text":"«Nuestra ciudad era tranquila hasta que llegaron los de afuera. Desde entonces hay más robos y menos trabajo. Si votan por mí, haré que esta ciudad vuelva a ser de los nuestros.»","svg":null,"table":null}'::jsonb, '¿Qué estrategia usa el candidato para ganar apoyo?', '[{"label":"A","text":"Reconocer los aportes de quienes llegaron a la ciudad.","is_correct":false,"distractor_type":"Invierte el mensaje.","explanation_feedback":"Incorrecta. El discurso culpa a quienes llegaron."},{"label":"B","text":"Crear un enemigo común para unir a sus votantes en torno a él.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Divide entre «los nuestros» y «los de afuera» y se presenta como quien resolverá el problema."},{"label":"C","text":"Proponer un plan detallado de empleo.","is_correct":false,"distractor_type":"Inventa una propuesta.","explanation_feedback":"Incorrecta. El discurso no explica ningún plan."},{"label":"D","text":"Presentar estadísticas de seguridad verificables.","is_correct":false,"distractor_type":"Supone que el discurso usa datos.","explanation_feedback":"Incorrecta. El discurso no presenta cifras ni fuentes."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E3.3'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'edefefeb-2abb-5d1b-8f32-6d4833d364b9', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Un discurso de campaña (ficticio)","text":"«Nuestra ciudad era tranquila hasta que llegaron los de afuera. Desde entonces hay más robos y menos trabajo. Si votan por mí, haré que esta ciudad vuelva a ser de los nuestros.»","svg":null,"table":null}'::jsonb, '¿Por qué un discurso así podría tener éxito entre algunos votantes?', '[{"label":"A","text":"Porque los votantes siempre eligen al candidato más joven.","is_correct":false,"distractor_type":"Inventa una regla.","explanation_feedback":"Incorrecta. El texto no habla de la edad del candidato."},{"label":"B","text":"Porque la ley obliga a votar por quien promete seguridad.","is_correct":false,"distractor_type":"Inventa una norma.","explanation_feedback":"Incorrecta. No existe tal obligación."},{"label":"C","text":"Porque ofrece una explicación simple a problemas complejos que generan miedo.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Señalar a un grupo como culpable da una respuesta fácil a la inseguridad y el desempleo."},{"label":"D","text":"Porque se basa en estudios económicos rigurosos.","is_correct":false,"distractor_type":"Supone que el discurso usa evidencia.","explanation_feedback":"Incorrecta. El discurso no menciona estudios."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E4.2'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'ebb38342-2e61-51f6-97ac-3150a2ff6078', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Trabajo infantil en la cosecha","text":"En una vereda cafetera, algunos niños de 12 y 13 años faltan al colegio durante la cosecha para ayudar a recoger café.\nPadre de familia: «Si no ayudan, no alcanzamos a recoger y perdemos la cosecha. Así aprendí yo.»\nRectora: «Pierden semanas de clase y muchos terminan repitiendo el año.»\nFuncionaria del ICBF: «La ley prohíbe el trabajo de menores de 15 años; es nuestro deber proteger sus derechos.»","svg":null,"table":null}'::jsonb, '¿En qué se diferencia la perspectiva del padre de la de la rectora?', '[{"label":"A","text":"El padre se enfoca en la economía familiar y la rectora en la educación de los niños.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Cada uno evalúa la situación desde su responsabilidad principal."},{"label":"B","text":"Ambos piensan que los niños deberían dejar de estudiar.","is_correct":false,"distractor_type":"Ignora la posición de la rectora.","explanation_feedback":"Incorrecta. La rectora defiende que no pierdan clases."},{"label":"C","text":"El padre cita la ley y la rectora la tradición.","is_correct":false,"distractor_type":"Invierte los argumentos.","explanation_feedback":"Incorrecta. El padre apela a la tradición («Así aprendí yo»); la ley la cita la funcionaria."},{"label":"D","text":"Ninguno menciona a los niños en sus argumentos.","is_correct":false,"distractor_type":"Lee mal el texto.","explanation_feedback":"Incorrecta. Ambos hablan de los niños."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E4.1'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '054f44e8-1a39-511d-a4cd-2011edaa4854', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Trabajo infantil en la cosecha","text":"En una vereda cafetera, algunos niños de 12 y 13 años faltan al colegio durante la cosecha para ayudar a recoger café.\nPadre de familia: «Si no ayudan, no alcanzamos a recoger y perdemos la cosecha. Así aprendí yo.»\nRectora: «Pierden semanas de clase y muchos terminan repitiendo el año.»\nFuncionaria del ICBF: «La ley prohíbe el trabajo de menores de 15 años; es nuestro deber proteger sus derechos.»","svg":null,"table":null}'::jsonb, '¿Qué influye en la frase del padre «Así aprendí yo»?', '[{"label":"A","text":"Una tradición familiar que considera normal que los niños trabajen en la cosecha.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Apela a su propia experiencia y a la costumbre como justificación."},{"label":"B","text":"El deseo de que sus hijos pierdan el año.","is_correct":false,"distractor_type":"Atribuye una intención que no expresa.","explanation_feedback":"Incorrecta. El padre no dice que quiera eso; su preocupación es la cosecha."},{"label":"C","text":"Un estudio científico sobre el aprendizaje infantil.","is_correct":false,"distractor_type":"Supone una base científica.","explanation_feedback":"Incorrecta. El padre habla de su experiencia, no de estudios."},{"label":"D","text":"Una norma del Ministerio de Educación.","is_correct":false,"distractor_type":"Inventa una norma.","explanation_feedback":"Incorrecta. No cita ninguna norma."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E4.2'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'f299672f-1a1c-5b2b-ba73-d225e918ccff', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Trabajo infantil en la cosecha","text":"En una vereda cafetera, algunos niños de 12 y 13 años faltan al colegio durante la cosecha para ayudar a recoger café.\nPadre de familia: «Si no ayudan, no alcanzamos a recoger y perdemos la cosecha. Así aprendí yo.»\nRectora: «Pierden semanas de clase y muchos terminan repitiendo el año.»\nFuncionaria del ICBF: «La ley prohíbe el trabajo de menores de 15 años; es nuestro deber proteger sus derechos.»","svg":null,"table":null}'::jsonb, '¿Qué medida atendería tanto la preocupación del padre como los derechos de los niños?', '[{"label":"A","text":"Permitir que los niños trabajen si sacan buenas notas.","is_correct":false,"distractor_type":"Desconoce la prohibición legal.","explanation_feedback":"Incorrecta. La ley prohíbe el trabajo de menores de 15 años."},{"label":"B","text":"Multar a las familias sin ofrecer ninguna alternativa.","is_correct":false,"distractor_type":"Atiende solo la norma.","explanation_feedback":"Incorrecta. No resuelve el problema económico del padre."},{"label":"C","text":"Cerrar el colegio durante toda la cosecha.","is_correct":false,"distractor_type":"Sacrifica la educación.","explanation_feedback":"Incorrecta. Los niños seguirían perdiendo clases."},{"label":"D","text":"Apoyar a las familias para contratar recolectores adultos y ajustar el calendario escolar con refuerzos.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Resuelve la falta de mano de obra sin que los niños trabajen ni pierdan clases."}]'::jsonb, null, 1.3, 1.3, 0.25, 90, 'original_generated'
from public.evidences e where e.code = 'SC.E4.3'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '9fa66b19-016c-5e11-b015-f89113961ab3', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Dos mapas de Colombia","text":"Un mapa de 1890 muestra a Panamá como parte de Colombia y gran parte de la Amazonía sin nombres de poblaciones. Un mapa de 2020 no incluye a Panamá y muestra en la Amazonía resguardos indígenas, parques nacionales y municipios.","svg":null,"table":null}'::jsonb, '¿Qué hecho histórico explica la diferencia sobre Panamá entre los dos mapas?', '[{"label":"A","text":"La independencia de España en 1810.","is_correct":false,"distractor_type":"Confunde la fecha.","explanation_feedback":"Incorrecta. En 1890 Colombia ya era independiente y Panamá seguía siendo parte de ella."},{"label":"B","text":"La Constitución de 1991.","is_correct":false,"distractor_type":"Confunde la fecha.","explanation_feedback":"Incorrecta. Panamá se separó mucho antes, en 1903."},{"label":"C","text":"El Frente Nacional.","is_correct":false,"distractor_type":"Confunde la fecha.","explanation_feedback":"Incorrecta. El Frente Nacional fue entre 1958 y 1974."},{"label":"D","text":"La separación de Panamá en 1903.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Panamá se separó de Colombia en 1903, por eso aparece en el mapa de 1890 y no en el de 2020."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
from public.evidences e where e.code = 'SC.E3.1'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'a9866a77-9da8-5297-8439-488c4ca0965a', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Dos mapas de Colombia","text":"Un mapa de 1890 muestra a Panamá como parte de Colombia y gran parte de la Amazonía sin nombres de poblaciones. Un mapa de 2020 no incluye a Panamá y muestra en la Amazonía resguardos indígenas, parques nacionales y municipios.","svg":null,"table":null}'::jsonb, '¿Qué no se puede concluir solo a partir de que el mapa de 1890 no tenga nombres en la Amazonía?', '[{"label":"A","text":"Que los mapas cambian con el tiempo.","is_correct":false,"distractor_type":"Esa sí es una conclusión razonable.","explanation_feedback":"Incorrecta. Comparar los dos mapas sí muestra cambios."},{"label":"B","text":"Que el mapa de 1890 tenía menos información sobre esa región.","is_correct":false,"distractor_type":"Esa sí es una conclusión razonable.","explanation_feedback":"Incorrecta. Esa conclusión sí se puede sacar del mapa."},{"label":"C","text":"Que el mapa de 2020 muestra resguardos indígenas.","is_correct":false,"distractor_type":"Esa es información directa.","explanation_feedback":"Incorrecta. El texto dice que el mapa de 2020 los muestra."},{"label":"D","text":"Que en la Amazonía no vivía nadie en esa época.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Que un mapa no registre poblaciones no prueba que no existieran; puede reflejar lo que el Estado conocía o reconocía."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E3.2'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '49164588-9465-5ece-93ee-ea893ece15ed', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Uniformes y libertad","text":"Columna de opinión de una estudiante (ficticia): «Los uniformes nos quitan la posibilidad de expresar quiénes somos. Además, muchas familias tienen que comprar uniformes costosos que solo venden en un almacén. Un colegio que enseña la libertad debería empezar por respetar cómo nos vestimos.»\nRespuesta del rector: «El uniforme evita que los estudiantes sean juzgados por la ropa que pueden comprar y ayuda a identificar quién pertenece al colegio por seguridad.»","svg":null,"table":null}'::jsonb, '¿En qué coinciden la estudiante y el rector, aunque lleguen a conclusiones distintas?', '[{"label":"A","text":"Ambos hablan de la seguridad del colegio.","is_correct":false,"distractor_type":"Atribuye a la estudiante el argumento del rector.","explanation_feedback":"Incorrecta. La seguridad la menciona solo el rector."},{"label":"B","text":"Ambos defienden la libertad de expresión.","is_correct":false,"distractor_type":"Atribuye al rector el argumento de la estudiante.","explanation_feedback":"Incorrecta. La libre expresión la menciona solo la estudiante."},{"label":"C","text":"Ambos quieren eliminar el uniforme.","is_correct":false,"distractor_type":"Ignora la posición del rector.","explanation_feedback":"Incorrecta. El rector defiende el uniforme."},{"label":"D","text":"Ambos se preocupan por el costo o la desigualdad económica entre familias.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Ella menciona uniformes costosos; él, que se juzgue a los estudiantes por la ropa que pueden comprar."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E4.1'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '84acb9c6-02b7-5b89-a15d-3e62991e1930', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Uniformes y libertad","text":"Columna de opinión de una estudiante (ficticia): «Los uniformes nos quitan la posibilidad de expresar quiénes somos. Además, muchas familias tienen que comprar uniformes costosos que solo venden en un almacén. Un colegio que enseña la libertad debería empezar por respetar cómo nos vestimos.»\nRespuesta del rector: «El uniforme evita que los estudiantes sean juzgados por la ropa que pueden comprar y ayuda a identificar quién pertenece al colegio por seguridad.»","svg":null,"table":null}'::jsonb, '¿Qué dato ayudaría a evaluar el argumento de la estudiante sobre el costo?', '[{"label":"A","text":"Saber cuántos años lleva el rector en el cargo.","is_correct":false,"distractor_type":"Elige un dato irrelevante.","explanation_feedback":"Incorrecta. La antigüedad del rector no evalúa el argumento."},{"label":"B","text":"Contar cuántas columnas de opinión publica el periódico.","is_correct":false,"distractor_type":"Elige un dato irrelevante.","explanation_feedback":"Incorrecta. No informa sobre el costo de los uniformes."},{"label":"C","text":"Comparar el precio del uniforme con lo que gastan las familias en ropa de diario.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Ese dato permitiría saber si el uniforme realmente es más costoso."},{"label":"D","text":"Saber cuál es el color favorito de los estudiantes.","is_correct":false,"distractor_type":"Elige un dato irrelevante.","explanation_feedback":"Incorrecta. El color no dice nada sobre el costo."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E3.2'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'df0e6799-643f-517e-8a43-8910b2efbe98', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"La consulta en el municipio minero","text":"En un municipio, una empresa quiere abrir una mina de oro. Parte de la población dice que traerá empleo e impuestos; otra parte teme que contamine las fuentes de agua de las que dependen los cultivos. El concejo convocó una consulta popular y el 70 % de los votantes dijo no a la minería.","svg":null,"table":null}'::jsonb, '¿Qué temen quienes se oponen a la mina?', '[{"label":"A","text":"Que se contaminen las fuentes de agua de los cultivos.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El texto dice que temen la contaminación del agua de la que dependen los cultivos."},{"label":"B","text":"Que no haya suficientes empleos en la mina.","is_correct":false,"distractor_type":"Confunde los argumentos a favor.","explanation_feedback":"Incorrecta. El empleo lo mencionan quienes apoyan la mina."},{"label":"C","text":"Que el oro pierda valor en el mercado.","is_correct":false,"distractor_type":"Inventa un argumento.","explanation_feedback":"Incorrecta. El texto no menciona el precio del oro."},{"label":"D","text":"Que el municipio reciba demasiados impuestos.","is_correct":false,"distractor_type":"Confunde los argumentos a favor.","explanation_feedback":"Incorrecta. Los impuestos son un argumento a favor."}]'::jsonb, null, 0.9, -1.2, 0.25, 40, 'original_generated'
from public.evidences e where e.code = 'SC.E4.1'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '18b87566-53db-5b42-b8c7-1397c6f1acb8', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"La consulta en el municipio minero","text":"En un municipio, una empresa quiere abrir una mina de oro. Parte de la población dice que traerá empleo e impuestos; otra parte teme que contamine las fuentes de agua de las que dependen los cultivos. El concejo convocó una consulta popular y el 70 % de los votantes dijo no a la minería.","svg":null,"table":null}'::jsonb, '¿Qué tipo de actividad económica probablemente tienen quienes votaron no?', '[{"label":"A","text":"La banca internacional.","is_correct":false,"distractor_type":"Elige una actividad sin relación.","explanation_feedback":"Incorrecta. El texto no da pistas sobre banca."},{"label":"B","text":"La agricultura, que depende del agua.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Su preocupación por el agua de los cultivos sugiere que viven de la agricultura."},{"label":"C","text":"La venta de maquinaria minera.","is_correct":false,"distractor_type":"Supone intereses opuestos a su voto.","explanation_feedback":"Incorrecta. Ese grupo se beneficiaría de la mina."},{"label":"D","text":"La minería de oro.","is_correct":false,"distractor_type":"Supone que los mineros se oponen a su actividad.","explanation_feedback":"Incorrecta. Quienes viven de la minería tenderían a apoyarla."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E4.2'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'a4c27d8e-2616-5199-991b-b786f5d2df43', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"La consulta en el municipio minero","text":"En un municipio, una empresa quiere abrir una mina de oro. Parte de la población dice que traerá empleo e impuestos; otra parte teme que contamine las fuentes de agua de las que dependen los cultivos. El concejo convocó una consulta popular y el 70 % de los votantes dijo no a la minería.","svg":null,"table":null}'::jsonb, '¿Qué dimensiones del problema están en tensión en esta situación?', '[{"label":"A","text":"La religiosa, por las creencias, y la deportiva.","is_correct":false,"distractor_type":"Elige dimensiones sin relación.","explanation_feedback":"Incorrecta. El texto no habla de religión ni deporte."},{"label":"B","text":"Solo la política, porque hubo una votación.","is_correct":false,"distractor_type":"Reduce el problema a una dimensión.","explanation_feedback":"Incorrecta. La votación fue el mecanismo; el conflicto es económico y ambiental."},{"label":"C","text":"La económica, por el empleo y los impuestos, y la ambiental, por el agua.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La discusión enfrenta beneficios económicos con riesgos ambientales."},{"label":"D","text":"La militar y la de las relaciones internacionales.","is_correct":false,"distractor_type":"Elige dimensiones sin relación.","explanation_feedback":"Incorrecta. El texto no menciona ejército ni otros países."}]'::jsonb, null, 1.3, 1.3, 0.25, 60, 'original_generated'
from public.evidences e where e.code = 'SC.E6.1'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'b7cf1d03-adba-5f4f-a9b5-b75b10b7e7db', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Lenguaje en las noticias","text":"Titular 1: «Invasores se toman un lote en la periferia.»\nTitular 2: «Familias sin vivienda ocupan un lote en la periferia.»\nAmbos titulares se refieren al mismo hecho.","svg":null,"table":null}'::jsonb, '¿Qué diferencia hay entre los dos titulares?', '[{"label":"A","text":"El primero presenta a las personas de forma negativa y el segundo destaca su necesidad.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. «Invasores» sugiere ilegitimidad; «familias sin vivienda» resalta la necesidad."},{"label":"B","text":"El primero describe un hecho distinto al segundo.","is_correct":false,"distractor_type":"Ignora que hablan del mismo hecho.","explanation_feedback":"Incorrecta. El texto dice que se refieren al mismo hecho."},{"label":"C","text":"El segundo usa un lenguaje más agresivo.","is_correct":false,"distractor_type":"Invierte la valoración.","explanation_feedback":"Incorrecta. El lenguaje negativo está en el primero."},{"label":"D","text":"Ninguno muestra una valoración sobre las personas.","is_correct":false,"distractor_type":"Ignora la carga de las palabras.","explanation_feedback":"Incorrecta. La elección de palabras sí transmite una valoración."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E3.3'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '99fb906d-cf14-5d31-8fdd-19e1e63fe5e1', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Lenguaje en las noticias","text":"Titular 1: «Invasores se toman un lote en la periferia.»\nTitular 2: «Familias sin vivienda ocupan un lote en la periferia.»\nAmbos titulares se refieren al mismo hecho.","svg":null,"table":null}'::jsonb, '¿Qué intención podría tener un medio que elige el titular 1?', '[{"label":"A","text":"Explicar las causas de la falta de vivienda.","is_correct":false,"distractor_type":"Inventa contenido.","explanation_feedback":"Incorrecta. El titular no habla de causas."},{"label":"B","text":"Despertar solidaridad con las familias.","is_correct":false,"distractor_type":"Atribuye la intención del titular 2.","explanation_feedback":"Incorrecta. Esa intención corresponde mejor al titular 2."},{"label":"C","text":"Generar rechazo hacia las personas que ocupan el lote.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La palabra «invasores» predispone al lector en contra de quienes ocupan el lote."},{"label":"D","text":"Informar sin ninguna valoración.","is_correct":false,"distractor_type":"Supone neutralidad.","explanation_feedback":"Incorrecta. La palabra elegida tiene una carga negativa."}]'::jsonb, null, 1.3, 1.3, 0.25, 60, 'original_generated'
from public.evidences e where e.code = 'SC.E3.3'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '7542f0c4-a7a7-53f7-bfc9-50aef8477074', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"La vía bloqueada","text":"Comunidades indígenas del Cauca bloquearon durante una semana la vía Panamericana. Dicen que el Gobierno no ha cumplido acuerdos firmados sobre tierras y salud. Los transportadores reportan pérdidas porque la carga no puede pasar. El Gobierno pide levantar el bloqueo para empezar a negociar, y las comunidades responden que solo lo levantarán cuando haya compromisos con fechas.","svg":null,"table":null}'::jsonb, '¿Por qué bloquearon la vía las comunidades indígenas?', '[{"label":"A","text":"Porque la vía estaba dañada por las lluvias.","is_correct":false,"distractor_type":"Inventa un motivo.","explanation_feedback":"Incorrecta. El bloqueo fue una forma de protesta."},{"label":"B","text":"Porque consideran que el Gobierno incumplió acuerdos sobre tierras y salud.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El texto dice que reclaman el incumplimiento de acuerdos firmados."},{"label":"C","text":"Porque querían cobrar peaje a los transportadores.","is_correct":false,"distractor_type":"Inventa un motivo.","explanation_feedback":"Incorrecta. El texto no habla de peajes."},{"label":"D","text":"Porque el Gobierno les pidió que lo hicieran.","is_correct":false,"distractor_type":"Invierte la relación.","explanation_feedback":"Incorrecta. El Gobierno pide levantar el bloqueo."}]'::jsonb, null, 0.9, -1.2, 0.25, 40, 'original_generated'
from public.evidences e where e.code = 'SC.E4.1'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'd090a781-a005-5aca-b016-f793d9c92a8d', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"La vía bloqueada","text":"Comunidades indígenas del Cauca bloquearon durante una semana la vía Panamericana. Dicen que el Gobierno no ha cumplido acuerdos firmados sobre tierras y salud. Los transportadores reportan pérdidas porque la carga no puede pasar. El Gobierno pide levantar el bloqueo para empezar a negociar, y las comunidades responden que solo lo levantarán cuando haya compromisos con fechas.","svg":null,"table":null}'::jsonb, '¿En qué se diferencian las condiciones que ponen el Gobierno y las comunidades?', '[{"label":"A","text":"El Gobierno quiere levantar el bloqueo antes de negociar y las comunidades quieren compromisos antes de levantarlo.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Cada parte quiere que la otra ceda primero."},{"label":"B","text":"Ambos quieren mantener el bloqueo indefinidamente.","is_correct":false,"distractor_type":"Ignora la posición del Gobierno.","explanation_feedback":"Incorrecta. El Gobierno pide levantarlo."},{"label":"C","text":"El Gobierno exige fechas y las comunidades se niegan a negociar.","is_correct":false,"distractor_type":"Invierte las posiciones.","explanation_feedback":"Incorrecta. Son las comunidades quienes piden compromisos con fechas."},{"label":"D","text":"Las comunidades piden dinero y el Gobierno pide tierras.","is_correct":false,"distractor_type":"Invierte y deforma los reclamos.","explanation_feedback":"Incorrecta. Las tierras las piden las comunidades."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E4.1'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '500a1ba7-8f82-5cb3-a7b7-0552470f4543', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"La vía bloqueada","text":"Comunidades indígenas del Cauca bloquearon durante una semana la vía Panamericana. Dicen que el Gobierno no ha cumplido acuerdos firmados sobre tierras y salud. Los transportadores reportan pérdidas porque la carga no puede pasar. El Gobierno pide levantar el bloqueo para empezar a negociar, y las comunidades responden que solo lo levantarán cuando haya compromisos con fechas.","svg":null,"table":null}'::jsonb, '¿Qué salida tiene en cuenta las posiciones de las tres partes mencionadas?', '[{"label":"A","text":"Desviar la carga por otro país mientras pasa el conflicto.","is_correct":false,"distractor_type":"Propone una salida poco viable que no resuelve el conflicto.","explanation_feedback":"Incorrecta. No atiende los reclamos ni la negociación."},{"label":"B","text":"Mantener el bloqueo hasta que el Gobierno cumpla todo.","is_correct":false,"distractor_type":"Atiende solo a las comunidades.","explanation_feedback":"Incorrecta. Ignora las pérdidas de los transportadores."},{"label":"C","text":"Desalojar la vía con la fuerza pública sin negociar.","is_correct":false,"distractor_type":"Atiende solo la urgencia de la vía.","explanation_feedback":"Incorrecta. Ignora los reclamos de las comunidades."},{"label":"D","text":"Abrir un paso humanitario para la carga mientras se firma un cronograma verificable de cumplimiento.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Reduce las pérdidas de los transportadores, da garantías a las comunidades y abre la negociación que pide el Gobierno."}]'::jsonb, null, 1.3, 1.3, 0.25, 90, 'original_generated'
from public.evidences e where e.code = 'SC.E4.3'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'e930824b-3f22-5386-814a-8f2c84c88985', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Una constitución federal (fragmento adaptado)","text":"«Los Estados soberanos de Antioquia, Bolívar, Boyacá, Cauca, Cundinamarca, Magdalena, Panamá, Santander y Tolima se unen y confederan para siempre, y forman una nación libre, soberana e independiente, bajo el nombre de Estados Unidos de Colombia.»\n(Adaptado del artículo 1 de la Constitución de Rionegro, 1863.)","svg":null,"table":null}'::jsonb, '¿Qué modelo de organización del Estado expresa este fragmento?', '[{"label":"A","text":"Una monarquía con un rey como jefe de Estado.","is_correct":false,"distractor_type":"Confunde formas de gobierno.","explanation_feedback":"Incorrecta. El fragmento no menciona un rey."},{"label":"B","text":"Un modelo federal, en el que los estados conservan amplia autonomía.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Habla de estados «soberanos» que se unen: es la base del federalismo de 1863."},{"label":"C","text":"Un Estado social de derecho como el de 1991.","is_correct":false,"distractor_type":"Confunde épocas.","explanation_feedback":"Incorrecta. Ese modelo es de la Constitución de 1991."},{"label":"D","text":"Un modelo centralista, en el que todo se decide desde la capital.","is_correct":false,"distractor_type":"Confunde con la Constitución de 1886.","explanation_feedback":"Incorrecta. La de 1886 fue centralista; este fragmento muestra lo contrario."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
from public.evidences e where e.code = 'SC.E3.1'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '88d3d60a-eb41-5107-9800-f37e84c3bacc', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Una constitución federal (fragmento adaptado)","text":"«Los Estados soberanos de Antioquia, Bolívar, Boyacá, Cauca, Cundinamarca, Magdalena, Panamá, Santander y Tolima se unen y confederan para siempre, y forman una nación libre, soberana e independiente, bajo el nombre de Estados Unidos de Colombia.»\n(Adaptado del artículo 1 de la Constitución de Rionegro, 1863.)","svg":null,"table":null}'::jsonb, '¿Qué grupo político del siglo XIX defendía con más fuerza el modelo que muestra este fragmento?', '[{"label":"A","text":"Los realistas que apoyaban a la Corona española.","is_correct":false,"distractor_type":"Confunde épocas.","explanation_feedback":"Incorrecta. En 1863 la independencia ya se había consolidado."},{"label":"B","text":"Los regeneradores, que impulsaron la Constitución de 1886.","is_correct":false,"distractor_type":"Confunde a los defensores del centralismo.","explanation_feedback":"Incorrecta. La Regeneración impulsó el centralismo de 1886."},{"label":"C","text":"Los liberales radicales, que buscaban limitar el poder del gobierno central.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La Constitución de Rionegro fue obra del liberalismo radical, partidario del federalismo."},{"label":"D","text":"Los partidos de izquierda del siglo XX.","is_correct":false,"distractor_type":"Confunde épocas.","explanation_feedback":"Incorrecta. El fragmento es de 1863."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E3.1'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '9b15e538-2b9b-5c5e-a377-d5c88bfa70a4', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Una constitución federal (fragmento adaptado)","text":"«Los Estados soberanos de Antioquia, Bolívar, Boyacá, Cauca, Cundinamarca, Magdalena, Panamá, Santander y Tolima se unen y confederan para siempre, y forman una nación libre, soberana e independiente, bajo el nombre de Estados Unidos de Colombia.»\n(Adaptado del artículo 1 de la Constitución de Rionegro, 1863.)","svg":null,"table":null}'::jsonb, '¿Cuál de los estados nombrados ya no hace parte de Colombia?', '[{"label":"A","text":"Tolima.","is_correct":false,"distractor_type":"No reconoce la continuidad del territorio.","explanation_feedback":"Incorrecta. Tolima sigue siendo un departamento de Colombia."},{"label":"B","text":"Boyacá.","is_correct":false,"distractor_type":"No reconoce la continuidad del territorio.","explanation_feedback":"Incorrecta. Boyacá sigue siendo un departamento de Colombia."},{"label":"C","text":"Antioquia.","is_correct":false,"distractor_type":"No reconoce la continuidad del territorio.","explanation_feedback":"Incorrecta. Antioquia sigue siendo un departamento de Colombia."},{"label":"D","text":"Panamá.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Panamá se separó de Colombia en 1903."}]'::jsonb, null, 0.9, -1.2, 0.25, 40, 'original_generated'
from public.evidences e where e.code = 'SC.E2.1'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'c43f97d7-e8a5-5989-b06c-d14364d9155c', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Murales en el centro","text":"En el centro de una ciudad, un colectivo de jóvenes pintó murales sobre la historia del barrio. Algunos comerciantes dicen que ensucian las fachadas y espantan a los clientes. Una guía turística afirma que desde que aparecieron los murales llegan más visitantes. La alcaldía estudia crear un reglamento.","svg":null,"table":null}'::jsonb, '¿Qué opina la guía turística de los murales?', '[{"label":"A","text":"Que la alcaldía debe prohibirlos.","is_correct":false,"distractor_type":"Inventa una opinión.","explanation_feedback":"Incorrecta. Ella no habla de prohibirlos."},{"label":"B","text":"Que deben borrarse de inmediato.","is_correct":false,"distractor_type":"Inventa una opinión.","explanation_feedback":"Incorrecta. Ella no propone borrarlos."},{"label":"C","text":"Que atraen más visitantes al centro.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Ella afirma que desde que aparecieron llegan más visitantes."},{"label":"D","text":"Que ensucian las fachadas.","is_correct":false,"distractor_type":"Le atribuye la opinión de los comerciantes.","explanation_feedback":"Incorrecta. Eso lo dicen algunos comerciantes."}]'::jsonb, null, 0.9, -1.2, 0.25, 40, 'original_generated'
from public.evidences e where e.code = 'SC.E4.1'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '0957a891-b08d-5579-aaf9-e520b2275276', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Murales en el centro","text":"En el centro de una ciudad, un colectivo de jóvenes pintó murales sobre la historia del barrio. Algunos comerciantes dicen que ensucian las fachadas y espantan a los clientes. Una guía turística afirma que desde que aparecieron los murales llegan más visitantes. La alcaldía estudia crear un reglamento.","svg":null,"table":null}'::jsonb, '¿Qué reglamento tendría en cuenta a comerciantes y artistas?', '[{"label":"A","text":"Uno que cobre un impuesto a los turistas.","is_correct":false,"distractor_type":"Propone algo sin relación.","explanation_feedback":"Incorrecta. No resuelve la tensión entre comerciantes y artistas."},{"label":"B","text":"Uno que prohíba cualquier pintura en el centro.","is_correct":false,"distractor_type":"Responde solo a los comerciantes.","explanation_feedback":"Incorrecta. Deja sin espacio a los artistas."},{"label":"C","text":"Uno que permita murales en muros acordados con los propietarios.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Protege la decisión de los dueños de las fachadas y da espacio a los artistas."},{"label":"D","text":"Uno que permita pintar cualquier fachada sin permiso.","is_correct":false,"distractor_type":"Responde solo a los artistas.","explanation_feedback":"Incorrecta. Ignora a los propietarios."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E4.3'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'dbdc4c97-dcf7-5a62-8748-2632f081de09', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"¿Qué fuente usar?","text":"Para una exposición sobre el voto femenino en Colombia, un grupo encontró: (1) el texto del Acto Legislativo 3 de 1954, que reconoció a las mujeres el derecho a votar; (2) un video de un canal de entretenimiento con «datos curiosos» de la historia, sin autores ni referencias; (3) un libro de una historiadora con notas a pie de página y fuentes de archivo; (4) un comentario anónimo en un foro.","svg":null,"table":null}'::jsonb, '¿Cuál es la fuente menos confiable para la exposición?', '[{"label":"A","text":"El texto del Acto Legislativo de 1954.","is_correct":false,"distractor_type":"Desconfía de un documento oficial.","explanation_feedback":"Incorrecta. Es una fuente primaria oficial muy útil."},{"label":"B","text":"El comentario anónimo en un foro.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. No se sabe quién lo escribió ni en qué se basa."},{"label":"C","text":"El libro de la historiadora.","is_correct":false,"distractor_type":"Desconfía de una fuente académica.","explanation_feedback":"Incorrecta. Tiene autoría, notas y fuentes de archivo."},{"label":"D","text":"Todas son igual de confiables.","is_correct":false,"distractor_type":"No evalúa las fuentes.","explanation_feedback":"Incorrecta. Las fuentes tienen distintos niveles de confiabilidad."}]'::jsonb, null, 0.9, -1.2, 0.25, 40, 'original_generated'
from public.evidences e where e.code = 'SC.E3.2'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'ed3fdbb7-7f5d-5820-b910-2ad051735510', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"¿Qué fuente usar?","text":"Para una exposición sobre el voto femenino en Colombia, un grupo encontró: (1) el texto del Acto Legislativo 3 de 1954, que reconoció a las mujeres el derecho a votar; (2) un video de un canal de entretenimiento con «datos curiosos» de la historia, sin autores ni referencias; (3) un libro de una historiadora con notas a pie de página y fuentes de archivo; (4) un comentario anónimo en un foro.","svg":null,"table":null}'::jsonb, '¿Qué tipo de fuente es el texto del Acto Legislativo 3 de 1954?', '[{"label":"A","text":"Una fuente secundaria, porque la escribió un historiador.","is_correct":false,"distractor_type":"Confunde con el libro.","explanation_feedback":"Incorrecta. El libro es la fuente secundaria."},{"label":"B","text":"Una fuente primaria, porque es un documento producido en la época del hecho.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Fue creado en 1954 como parte del hecho que se estudia."},{"label":"C","text":"Una fuente terciaria, como una enciclopedia.","is_correct":false,"distractor_type":"Confunde categorías.","explanation_feedback":"Incorrecta. Es un documento original de la época."},{"label":"D","text":"Una opinión personal sin valor histórico.","is_correct":false,"distractor_type":"Desconoce su carácter oficial.","explanation_feedback":"Incorrecta. Es una norma oficial."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
from public.evidences e where e.code = 'SC.E3.1'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '8108e418-4239-5a43-8fea-4e53f5e87359', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"¿Qué fuente usar?","text":"Para una exposición sobre el voto femenino en Colombia, un grupo encontró: (1) el texto del Acto Legislativo 3 de 1954, que reconoció a las mujeres el derecho a votar; (2) un video de un canal de entretenimiento con «datos curiosos» de la historia, sin autores ni referencias; (3) un libro de una historiadora con notas a pie de página y fuentes de archivo; (4) un comentario anónimo en un foro.","svg":null,"table":null}'::jsonb, '¿Para qué sirve más el libro de la historiadora que el Acto Legislativo?', '[{"label":"A","text":"Para entretener al público con datos curiosos.","is_correct":false,"distractor_type":"Le atribuye el propósito del video.","explanation_feedback":"Incorrecta. Ese es el propósito del video."},{"label":"B","text":"Para entender el contexto y los debates que llevaron al voto femenino.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Una investigación con fuentes de archivo explica causas, actores y debates."},{"label":"C","text":"Para conocer el texto exacto de la norma.","is_correct":false,"distractor_type":"Atribuye al libro lo que da mejor la fuente primaria.","explanation_feedback":"Incorrecta. El texto exacto está en el Acto Legislativo."},{"label":"D","text":"Para saber qué opinan usuarios anónimos.","is_correct":false,"distractor_type":"Le atribuye el contenido del foro.","explanation_feedback":"Incorrecta. Eso lo daría el foro."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'SC.E3.2'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '25e2a68d-f197-5e13-840f-75d26fc2b09f', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Turismo en el archipiélago","text":"En San Andrés, el número de turistas ha crecido mucho. Los hoteleros celebran el aumento de ingresos. Líderes del pueblo raizal, que tiene su propia lengua (el creole) y tradiciones, dicen que el turismo masivo encarece la vida, presiona el agua dulce y reduce los espacios de su cultura. Funcionarios ambientales advierten sobre el daño a los arrecifes de coral.","svg":null,"table":null}'::jsonb, '¿Qué preocupa a los funcionarios ambientales?', '[{"label":"A","text":"El daño a los arrecifes de coral.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El texto dice que advierten sobre el daño a los arrecifes."},{"label":"B","text":"El aumento de ingresos de los hoteles.","is_correct":false,"distractor_type":"Confunde con lo que celebran los hoteleros.","explanation_feedback":"Incorrecta. Eso lo celebran los hoteleros."},{"label":"C","text":"La pérdida de la lengua creole.","is_correct":false,"distractor_type":"Confunde con la preocupación raizal.","explanation_feedback":"Incorrecta. Eso lo plantean los líderes raizales."},{"label":"D","text":"La falta de turistas en la isla.","is_correct":false,"distractor_type":"Contradice el texto.","explanation_feedback":"Incorrecta. El texto dice que los turistas han aumentado."}]'::jsonb, null, 0.9, -1.2, 0.25, 40, 'original_generated'
from public.evidences e where e.code = 'SC.E4.1'
