insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '58f8ec95-95a5-5fbf-b4e7-faefa8e72ba4', e.id, 'SC', null, 'qa_passed', 'continuous', '{"title":"Turismo en el archipiélago","text":"En San Andrés, el número de turistas ha crecido mucho. Los hoteleros celebran el aumento de ingresos. Líderes del pueblo raizal, que tiene su propia lengua (el creole) y tradiciones, dicen que el turismo masivo encarece la vida, presiona el agua dulce y reduce los espacios de su cultura. Funcionarios ambientales advierten sobre el daño a los arrecifes de coral.","svg":null,"table":null}'::jsonb, '¿Por qué la perspectiva raizal incluye aspectos culturales que los hoteleros no mencionan?', '[{"label":"A","text":"Porque para el pueblo raizal la isla es su territorio ancestral y base de su identidad.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Su relación con el territorio va más allá de lo económico: incluye lengua, tradiciones y modos de vida."},{"label":"B","text":"Porque los hoteleros no viven en la isla.","is_correct":false,"distractor_type":"Inventa un dato.","explanation_feedback":"Incorrecta. El texto no dice dónde viven los hoteleros."},{"label":"C","text":"Porque la cultura no tiene relación con el turismo.","is_correct":false,"distractor_type":"Contradice el texto.","explanation_feedback":"Incorrecta. Los raizales dicen que el turismo reduce espacios de su cultura."},{"label":"D","text":"Porque los raizales no trabajan en turismo.","is_correct":false,"distractor_type":"Generaliza sin datos.","explanation_feedback":"Incorrecta. El texto no dice eso."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
